 * {@link #apply(String)} to perform its specific transformation.
 */
public enum TextStyle {
    /** Transforms the input string to upper case. */
    UPPERCASE {
        @Override
        public String apply(String input) {
            requireNonNull(input);
            return input.toUpperCase();
        }
    },
    /** Transforms the input string to lower case. */
    LOWERCASE {
        @Override
        public String apply(String input) {
            requireNonNull(input);
            return input.toLowerCase();
        }
    },
    /** Capitalizes the first letter of each word and lower‑cases the remaining letters. */
    CAPITALIZE_WORDS {
        @Override
        public String apply(String input) {
            requireNonNull(input);
            // Split on one or more whitespace characters
            String[] words = input.trim().split("\\s+");
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < words.length; i++) {
                if (words[i].isEmpty()) {
                    continue;
                }
                String word = words[i];
                sb.append(Character.toUpperCase(word.charAt(0)));
                if (word.length() > 1) {
                    sb.append(word.substring(1).toLowerCase());
                }
                if (i < words.length - 1) {
                    sb.append(' ');
                }
            }
            return sb.toString();
        }
    },
    /** Reverses the characters of the input string. */
    REVERSE {
        @Override
        public String apply(String input) {
            requireNonNull(input);
            return new StringBuilder(input).reverse().toString();
        }
    };

    /**
     * Applies the style‑specific transformation to {@code input}.
     *
     * @param input the string to transform; must not be {@code null}
     * @return the transformed string
     * @throws NullPointerException if {@code input} is {@code null}
     */
    public abstract String apply(String input);

    /** Helper that enforces the non‑null contract. */
    private static void requireNonNull(String input) {
        if (input == null) {
            throw new NullPointerException("input must not be null");
        }
    }
}
