class TextStyleTest {

    private static final String PACKAGE = "de.tum.cit.aet.exgenenumscarryingbehavior";

    private Class<?> loadTextStyle() throws ClassNotFoundException {
        return Class.forName(PACKAGE + ".TextStyle");
    }

    private Object enumConstant(Class<?> enumClass, String name) {
        @SuppressWarnings("unchecked")
        Class<? extends Enum<?>> ec = (Class<? extends Enum<?>>) enumClass;
        return Enum.valueOf(ec, name);
    }

    private Method getApplyMethod(Class<?> enumClass) throws NoSuchMethodException {
        return enumClass.getMethod("apply", String.class);
    }

    private Method getProcessorMethod(Class<?> enumClass) throws Exception {
        Class<?> processorClass = Class.forName(PACKAGE + ".TextProcessor");
        return processorClass.getMethod("applyStyle", enumClass, String.class);
    }

    @Test
    @StrictTimeout(1)
    void testUppercase() throws Exception {
        Class<?> styleClass = loadTextStyle();
        Object constant = enumConstant(styleClass, "UPPERCASE");
        Method apply = getApplyMethod(styleClass);
        String result = (String) apply.invoke(constant, "Hello World");
        assertEquals("HELLO WORLD", result);
    }

    @Test
    @StrictTimeout(1)
    void testLowercase() throws Exception {
        Class<?> styleClass = loadTextStyle();
        Object constant = enumConstant(styleClass, "LOWERCASE");
        Method apply = getApplyMethod(styleClass);
        String result = (String) apply.invoke(constant, "Hello World");
        assertEquals("hello world", result);
    }

    @Test
    @StrictTimeout(1)
    void testCapitalizeWords() throws Exception {
        Class<?> styleClass = loadTextStyle();
        Object constant = enumConstant(styleClass, "CAPITALIZE_WORDS");
        Method apply = getApplyMethod(styleClass);
        String result = (String) apply.invoke(constant, "java programming language");
        assertEquals("Java Programming Language", result);
    }

    @Test
    @StrictTimeout(1)
    void testReverse() throws Exception {
        Class<?> styleClass = loadTextStyle();
        Object constant = enumConstant(styleClass, "REVERSE");
        Method apply = getApplyMethod(styleClass);
        String result = (String) apply.invoke(constant, "abc");
        assertEquals("cba", result);
    }

    @Test
    @StrictTimeout(1)
    void testNullInputThrows() throws Exception {
        Class<?> styleClass = loadTextStyle();
        Object constant = enumConstant(styleClass, "UPPERCASE");
        Method apply = getApplyMethod(styleClass);
        assertThrows(NullPointerException.class, () -> {
            try {
                apply.invoke(constant, new Object[]{null});
            } catch (Exception e) {
                // unwrap InvocationTargetException
                throw e.getCause();
            }
        });
    }

    @Test
    @StrictTimeout(1)
    void testProcessorDelegates() throws Exception {
        Class<?> styleClass = loadTextStyle();
        Object constant = enumConstant(styleClass, "LOWERCASE");
        Method processorMethod = getProcessorMethod(styleClass);
        String result = (String) processorMethod.invoke(null, constant, "HeLLo");
        assertEquals("hello", result);
    }
}
